EchoServiceAsyncWaiter::EchoServiceAsyncWaiter(
    EchoService* proxy) : proxy_(proxy) {}

EchoServiceAsyncWaiter::~EchoServiceAsyncWaiter() = default;


void EchoServiceAsyncWaiter::EchoString(
    const std::string& input, std::string* out_echoed_input) {
  base::RunLoop loop;
  proxy_->EchoString(
      std::move(input),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_echoed_input
,
             const std::string& echoed_input) {*out_echoed_input = std::move(echoed_input);
            loop->Quit();
          },
          &loop,
          out_echoed_input));
  loop.Run();
}

std::string EchoServiceAsyncWaiter::EchoString(
    const std::string& input) {
  std::string async_wait_result;
  EchoString(std::move(input),&async_wait_result);
  return async_wait_result;
}

void EchoServiceAsyncWaiter::LoadNativeLibrary(
    const ::base::FilePath& library, bool call_winmm_delayload, EchoService::LoadStatus* out_status, uint32_t* out_error_code) {
  base::RunLoop loop;
  proxy_->LoadNativeLibrary(
      std::move(library),
      std::move(call_winmm_delayload),
      base::BindOnce(
          [](base::RunLoop* loop,
             EchoService::LoadStatus* out_status
,
             uint32_t* out_error_code
,
             EchoService::LoadStatus status,
             uint32_t error_code) {*out_status = std::move(status);*out_error_code = std::move(error_code);
            loop->Quit();
          },
          &loop,
          out_status,
          out_error_code));
  loop.Run();
}



void EchoServiceAsyncWaiter::DecryptEncrypt(
    ::scoped_refptr<::os_crypt_async::Encryptor> encryptor, const std::vector<uint8_t>& input, std::optional<std::vector<uint8_t>>* out_output) {
  base::RunLoop loop;
  proxy_->DecryptEncrypt(
      std::move(encryptor),
      std::move(input),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::optional<std::vector<uint8_t>>* out_output
,
             const std::optional<std::vector<uint8_t>>& output) {*out_output = std::move(output);
            loop->Quit();
          },
          &loop,
          out_output));
  loop.Run();
}

std::optional<std::vector<uint8_t>> EchoServiceAsyncWaiter::DecryptEncrypt(
    ::scoped_refptr<::os_crypt_async::Encryptor> encryptor, const std::vector<uint8_t>& input) {
  std::optional<std::vector<uint8_t>> async_wait_result;
  DecryptEncrypt(std::move(encryptor),std::move(input),&async_wait_result);
  return async_wait_result;
}

void EchoServiceAsyncWaiter::VerifyCheckIsTest(
    bool* out_is_test) {
  base::RunLoop loop;
  proxy_->VerifyCheckIsTest(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_is_test
,
             bool is_test) {*out_is_test = std::move(is_test);
            loop->Quit();
          },
          &loop,
          out_is_test));
  loop.Run();
}

bool EchoServiceAsyncWaiter::VerifyCheckIsTest(
    ) {
  bool async_wait_result;
  VerifyCheckIsTest(&async_wait_result);
  return async_wait_result;
}






